/** Is (lon, lat) on land? */
export function onLand(lon: number, lat: number): boolean {
  if (lon >= TR_BOX[0] && lon <= TR_BOX[2] && lat >= TR_BOX[1] && lat <= TR_BOX[3]) {
    for (const isl of TR_ISLANDS) if (inside(isl, lon, lat)) return true
    for (const sea of TR_SEA) if (inside(sea, lon, lat)) return false
    return true
  }
  for (let i = 0; i < WATER.length; i++) {
    const b = WATER_BOX[i]
    if (lon >= b[0] && lon <= b[2] && lat >= b[1] && lat <= b[3] && inside(WATER[i], lon, lat)) return false
  }
  for (let i = 0; i < LAND.length; i++) {
    const b = LAND_BOX[i]
    if (lon >= b[0] && lon <= b[2] && lat >= b[1] && lat <= b[3] && inside(LAND[i], lon, lat)) return true
  }
  return false
}

/** The shown latitudes (Antarctica and the far Arctic are left off). */
export const LAT_TOP = 84
export const LAT_BOTTOM = -57

const dotCache = new Map<string, Float32Array>()
/**
 * The land dots of a grid `step` degrees apart (rows offset half a step, a
 * honeycomb), inside [lon0..lon1] × [lat0..lat1]; flat [lon, lat, …].
 */
export function landDots(step: number, lon0 = -180, lon1 = 180, lat0 = LAT_BOTTOM, lat1 = LAT_TOP): Float32Array {
  const key = `${step}:${lon0}:${lon1}:${lat0}:${lat1}`
  let d = dotCache.get(key)
  if (d) return d
  const out: number[] = []
  for (let r = Math.ceil(lat0 / step); r * step <= lat1; r++) {
    const lat = r * step
    // Every other row sits half a step over — counted from the equator, so
    // neighbouring tiles agree and no seam shows between them.
    const off = ((r % 2) + 2) % 2 ? step / 2 : 0
    for (let lon = Math.ceil((lon0 - off) / step) * step + off; lon <= lon1; lon += step) if (lon >= lon0 && onLand(lon, lat)) out.push(lon, lat)
  }
  d = new Float32Array(out)
  if (dotCache.size > 6000) dotCache.clear()
  dotCache.set(key, d)
  return d
}

